export function search(a, target) {
  let lo = 0;
  let hi = a.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (a[mid] < target) lo = mid;
    else hi = mid;
  }
  return a[lo] === target ? lo : -1;
}

