import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
// Run in a child process with a timeout so a hang fails instead of freezing the grader
const run = (a, t) => JSON.parse(execFileSync(process.execPath, ['-e', `import('${new URL('../search.js', import.meta.url).href}').then(m => console.log(JSON.stringify(m.search(${JSON.stringify(a)}, ${t}))))`], { timeout: 3000 }).toString());
test('finds', () => { const a = [1, 3, 5, 7, 9, 11]; a.forEach((v, i) => assert.equal(run(a, v), i)); });
test('missing', () => { assert.equal(run([1, 3, 5], 4), -1); assert.equal(run([1, 3, 5], 6), -1); assert.equal(run([1, 3, 5], 0), -1); });
test('empty', () => assert.equal(run([], 1), -1));

